INSERT INTO products (id, category, type, name, price, original_price, image_url, images_json, sizes_json, unavailable_json, description, is_sale, is_active) VALUES
(1, 'men', 'Men''s Oxford', 'MCGUIRE in Dark Brown', 4784, 5980, 'https://bristolshoes.ph/cdn/shop/files/MCGUIRE_BROWN_SIDE_510x@2x.progressive.png.jpg?v=1763541249', '["https://bristolshoes.ph/cdn/shop/files/MCGUIRE_BROWN_SIDE_510x@2x.progressive.png.jpg?v=1763541249","https://bristolshoes.ph/cdn/shop/files/MCGUIRE_BROWN_DUO_510x@2x.progressive.png.jpg?v=1763541249"]', '[39,40,41,42,43,45]', '[44]', 'Elevate your formal look with these sleek dark brown leather shoes. Subtle brogue perforations and smooth polished finish. Upper: cow nappa leather. Lined with pigskin leather.', 1, 1),
(2, 'men', 'Men''s Oxford', 'MCGUIRE in Black', 4784, 5980, 'https://bristolshoes.ph/cdn/shop/files/MCGUIRE_BLACK_SIDE_510x@2x.progressive.png.jpg?v=1763540650', '["https://bristolshoes.ph/cdn/shop/files/MCGUIRE_BLACK_SIDE_510x@2x.progressive.png.jpg?v=1763540650","https://bristolshoes.ph/cdn/shop/files/MCGUIRE_BLACK_DUO_510x@2x.progressive.png.jpg?v=1763540672"]', '[39,40,41,42,43,44,45]', '[]', 'Elevate your formal look with these sleek black leather shoes. Subtle brogue perforations and smooth polished finish. Open-lace construction for a comfortable fit.', 1, 1),
(3, 'men', 'Men''s Oxford', 'BALFOUR in Brown', 4495, NULL, 'https://bristolshoes.ph/cdn/shop/files/BALFOUR_BROWN_sideview_510x@2x.progressive.jpg?v=1763535096', '["https://bristolshoes.ph/cdn/shop/files/BALFOUR_BROWN_sideview_510x@2x.progressive.jpg?v=1763535096","https://bristolshoes.ph/cdn/shop/files/BALFOUR_BROWN_duo_510x@2x.progressive.jpg?v=1763535096","https://bristolshoes.ph/cdn/shop/files/SOLE_PASEXY_NEW_510x@2x.progressive.jpg?v=1706518591"]', '[39,40,41,42,43,44,45]', '[]', 'An Oxford in brown brush-off leather with an interesting lacing design. Effortlessly transforms from formal to casual. Upper: cow brush-off leather. Lined with pigskin leather.', 0, 1),
(4, 'men', 'Men''s Loafer', 'BEDFORD in Tan Brown', 4495, NULL, 'https://bristolshoes.ph/cdn/shop/files/BEDFORD_TAN_SIDE_510x@2x.progressive.png.jpg?v=1757397457', '["https://bristolshoes.ph/cdn/shop/files/BEDFORD_TAN_SIDE_510x@2x.progressive.png.jpg?v=1757397457","https://bristolshoes.ph/cdn/shop/files/BEDFORD_TAN_DUO_510x@2x.progressive.png.jpg?v=1757397457","https://bristolshoes.ph/cdn/shop/files/SOLE_RSO_510x@2x.progressive.png.jpg?v=1757395891"]', '[39,40,41,42,43,44,45]', '[]', 'Handcrafted in Marikina by local artisans using the highest quality leather. Upper: cow nappa leather. Lined with pigskin leather. Outsole: rubber.', 0, 1),
(5, 'men', 'Men''s Loafer', 'FIYERO in Black', 5295, NULL, 'https://bristolshoes.ph/cdn/shop/files/FIYERO_BLACK_sideview_510x@2x.progressive.png.jpg?v=1763964977', '["https://bristolshoes.ph/cdn/shop/files/FIYERO_BLACK_sideview_510x@2x.progressive.png.jpg?v=1763964977","https://bristolshoes.ph/cdn/shop/files/FIYERO_BLACK_duo_510x@2x.progressive.png.jpg?v=1763964977","https://bristolshoes.ph/cdn/shop/files/SOLE_LEATHER_510x@2x.progressive.png.jpg?v=1757400779"]', '[39,40,41,42,43,44,45]', '[]', 'A polished leather monk strap with a sleek moc-toe design and standout silver buckle. Blends classic sophistication with modern flair. Perfect for formal events and office attire.', 0, 1),
(6, 'men', 'Men''s Loafer', 'FIYERO in Brown', 5295, NULL, 'https://bristolshoes.ph/cdn/shop/files/FIYERO_BROWN_sideview_510x@2x.progressive.png.jpg?v=1763965981', '["https://bristolshoes.ph/cdn/shop/files/FIYERO_BROWN_sideview_510x@2x.progressive.png.jpg?v=1763965981","https://bristolshoes.ph/cdn/shop/files/FIYERO_BROWN_duo_510x@2x.progressive.png.jpg?v=1763965981","https://bristolshoes.ph/cdn/shop/files/SOLE_LEATHER_BROWN_UPPER_510x@2x.progressive.png.jpg?v=1757401165"]', '[39,40,41,42,43,44,45]', '[]', 'A polished leather monk strap in warm brown with a standout silver buckle. Blends classic sophistication with modern flair.', 0, 1),
(7, 'women', 'Women''s Loafer', 'ISABELLA in Black', 3995, NULL, 'https://bristolshoes.ph/cdn/shop/files/ISABELLA_BLACK_sideview_510x@2x.progressive.jpg?v=1706086338', '["https://bristolshoes.ph/cdn/shop/files/ISABELLA_BLACK_sideview_510x@2x.progressive.jpg?v=1706086338","https://bristolshoes.ph/cdn/shop/files/ISABELLA_BLACK_DUO_510x@2x.progressive.jpg?v=1706086348","https://bristolshoes.ph/cdn/shop/files/ISABELLA_BLACK_top_510x@2x.progressive.jpg?v=1706086578","https://bristolshoes.ph/cdn/shop/files/ISABELLA_BLACK_zoomed_510x@2x.progressive.jpg?v=1706086798"]', '[35,36,37,38,39,40]', '[]', 'Look sharp and stay comfortable in the Isabella in Black. Handcrafted in Marikina by local artisans using the highest quality leather. All-day comfort you can depend on.', 0, 1),
(8, 'women', 'Women''s Loafer', 'ATHENA in Maroon', 3995, NULL, 'https://bristolshoes.ph/cdn/shop/files/ATHENAMSIDE_510x@2x.progressive.jpg?v=1702292746', '["https://bristolshoes.ph/cdn/shop/files/ATHENAMSIDE_510x@2x.progressive.jpg?v=1702292746","https://bristolshoes.ph/cdn/shop/files/ATHENAMDUO_510x@2x.progressive.jpg?v=1702292746","https://bristolshoes.ph/cdn/shop/files/ATHENA_Maroon_zoomed_510x@2x.progressive.jpg?v=1702293144","https://bristolshoes.ph/cdn/shop/files/SOLE_LADIES_SEMI-BULKY_70c773e0-d6d7-4615-a471-d06fc94c271d_510x@2x.progressive.jpg?v=1702292775"]', '[35,36,37,38,39,40]', '[]', 'A stylish penny loafer that captures attention and complements with just one look. Handcrafted in Marikina from the highest quality leather.', 0, 1),
(9, 'women', 'Women''s Loafer', 'ASHANTI in Black', 4295, NULL, 'https://bristolshoes.ph/cdn/shop/files/ASHANTI_K_sideview_510x@2x.progressive.jpg?v=1700119783', '["https://bristolshoes.ph/cdn/shop/files/ASHANTI_K_sideview_510x@2x.progressive.jpg?v=1700119783","https://bristolshoes.ph/cdn/shop/files/ASHANTI_K_duo_510x@2x.progressive.jpg?v=1700119783","https://bristolshoes.ph/cdn/shop/files/ASHANTI_K_z_510x@2x.progressive.jpg?v=1700119772","https://bristolshoes.ph/cdn/shop/files/SOLE_LADIES_SEMI-BULKY_ae73c166-d27d-44e7-a5bb-121c97920c84_510x@2x.progressive.jpg?v=1700119784"]', '[35,36,37,38,39,40]', '[]', 'A modern twist to the classic penny loafer. Color-blocking design makes a retro statement while the lug soles give it a modern edge. Handcrafted in Marikina.', 0, 1),
(10, 'women', 'Women''s Loafer', 'ASHANTI in Black & Red', 4295, NULL, 'https://bristolshoes.ph/cdn/shop/files/ASHANTI_KR_sideview_510x@2x.progressive.jpg?v=1700038433', '["https://bristolshoes.ph/cdn/shop/files/ASHANTI_KR_sideview_510x@2x.progressive.jpg?v=1700038433","https://bristolshoes.ph/cdn/shop/files/ASHANTI_KR_duo_510x@2x.progressive.jpg?v=1700038433","https://bristolshoes.ph/cdn/shop/files/ASHANTI_KR_z_510x@2x.progressive.jpg?v=1700038375","https://bristolshoes.ph/cdn/shop/files/SOLE_LADIES_SEMI-BULKY_86feca79-be0e-4baa-b693-de5aed184e23_510x@2x.progressive.jpg?v=1700038657"]', '[35,36,37,38,39,40]', '[38]', 'Bold color-blocking penny loafer in black and red. Retro design meets modern lug soles. Handcrafted in Marikina.', 0, 1),
(11, 'women', 'Women''s Oxford', 'LUCILLE in Black', 4295, NULL, 'https://bristolshoes.ph/cdn/shop/files/LUCILLE_BLACK_sideview_510x@2x.progressive.jpg?v=1706084670', '["https://bristolshoes.ph/cdn/shop/files/LUCILLE_BLACK_sideview_510x@2x.progressive.jpg?v=1706084670","https://bristolshoes.ph/cdn/shop/files/LUCILLE_BLACK_DUO_510x@2x.progressive.jpg?v=1706084670","https://bristolshoes.ph/cdn/shop/files/LUCILLE_BLACK_ZOOMED_510x@2x.progressive.jpg?v=1706084665","https://bristolshoes.ph/cdn/shop/files/LUCILLE_BLACK_TOP_510x@2x.progressive.jpg?v=1706084838"]', '[35,36,37,38,39,40]', '[]', 'Simple yet sophisticated the Lucille makes sure you stand apart from the crowd. Quality materials offer all-day comfort. Handcrafted in Marikina.', 0, 1),
(12, 'women', 'Women''s Mule', 'CHARLIZE in Black', 3795, NULL, 'https://bristolshoes.ph/cdn/shop/files/CHARLIZE_BLACK_SIDEVIEW_510x@2x.progressive.jpg?v=1692082976', '["https://bristolshoes.ph/cdn/shop/files/CHARLIZE_BLACK_SIDEVIEW_510x@2x.progressive.jpg?v=1692082976","https://bristolshoes.ph/cdn/shop/files/CHARLIZE_BLACK_DUO_510x@2x.progressive.jpg?v=1692085979","https://bristolshoes.ph/cdn/shop/files/CHARLIZE_BLACK_ZOOMED_510x@2x.progressive.jpg?v=1692085979"]', '[35,36,37,38,39,40]', '[]', 'The perfect shoe for a stylish yet comfortable slip-on. Simple and relaxed design with effortless style. Handcrafted in Marikina.', 0, 1)
